    async def create_easy_hunting_hunting_queue(
        self,
        *,
        billing_account: str,
        service_name: str,
        strategy: TelephonyOvhPabxHuntingQueueStrategyEnum,
        action_on_closure: TelephonyOvhPabxQueueActionEnum | None = None,
        action_on_closure_param: str | None = None,
        action_on_overflow: TelephonyOvhPabxQueueActionEnum | None = None,
        action_on_overflow_param: str | None = None,
        ask_for_record_disabling: bool | None = None,
        description: str | None = None,
        max_member: int | None = None,
        max_wait_time: int | None = None,
        record: bool | None = None,
        record_disabling_digit: int | None = None,
        record_disabling_language: TelephonyOvhPabxHuntingQueueRecordDisablingLanguageEnum
        | None = None,
        sound_on_hold: int | None = None,
    ) -> TelephonyOvhPabxHuntingQueue:
        """
        POST /1.0/telephony/{billingAccount}/easyHunting/{serviceName}/hunting/queue

        Create a queue

        Args:
            action_on_closure: Action executed when there is no member in queue
            action_on_closure_param: The additionnal parameter of the on closure action
            action_on_overflow: Action executed when caller enters a full queue
            action_on_overflow_param: The additionnal parameter of the overflow action
            ask_for_record_disabling: Allow the caller to disable call record by
                pressing a key
            billing_account: The name of your billingAccount
            description: The name of the queue
            max_member: The maximum of people waiting in the queue
            max_wait_time: The maximum waiting time (in seconds) in the queue
            record: Enable record on calls in queue
            record_disabling_digit: Key to press to disable record
            record_disabling_language: Language of the sound played to the caller to
                inform that he can disable record
            sound_on_hold: The id of the OvhPabxSound played to caller when on hold
            strategy: The calls dispatching strategy
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/1.0/telephony/{billingAccount}/easyHunting/{serviceName}/hunting/queue",
                billingAccount=billing_account,
                serviceName=service_name,
            ),
            body={
                "actionOnClosure": action_on_closure,
                "actionOnClosureParam": action_on_closure_param,
                "actionOnOverflow": action_on_overflow,
                "actionOnOverflowParam": action_on_overflow_param,
                "askForRecordDisabling": ask_for_record_disabling,
                "description": description,
                "maxMember": max_member,
                "maxWaitTime": max_wait_time,
                "record": record,
                "recordDisablingDigit": record_disabling_digit,
                "recordDisablingLanguage": record_disabling_language,
                "soundOnHold": sound_on_hold,
                "strategy": strategy,
            },
        )
        return TelephonyOvhPabxHuntingQueue.model_validate(data)

